describe('Navigation - Home to Example Page and Back', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should navigate from home page to example page and back', () => {
    // Verify home page is visible
    cy.get('[data-testid="content"]').should('be.visible');
    cy.get('[data-testid="Welcome to the-internet"]').should('contain', 'Welcome');

    // Click the A/B Testing link
    cy.get('[data-testid="A/B Testing"]').click();

    // Verify navigation to /abtest page
    cy.url().should('include', '/abtest');

    // Verify the page title or heading is visible
    cy.get('[data-testid="h3"]').should('be.visible');
    cy.get('[data-testid="h3"]').should('contain', 'A/B Testing');

    // Verify navigation back to home page
    cy.get('[data-testid="Home"]').click();

    // Verify home page is restored
    cy.url().should('include', '/');
    cy.get('[data-testid="Welcome to the-internet"]').should('be.visible');
    cy.get('[data-testid="Available Examples"]').should('be.visible');
  });

  it('should handle navigation to non-existent page and return to home', () => {
    // Verify home page is visible
    cy.get('[data-testid="content"]').should('be.visible');
    cy.get('[data-testid="Welcome to the-internet"]').should('contain', 'Welcome');

    // Click a non-existent link
    cy.get('[data-testid="Nested Frames"]').click();

    // Verify navigation to 404 page
    cy.url().should('include', '/404');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Page not found');

    // Verify navigation back to home page
    cy.get('[data-testid="Home"]').click();

    // Verify home page is restored
    cy.url().should('include', '/');
    cy.get('[data-testid="Welcome to the-internet"]').should('be.visible');
    cy.get('[data-testid="Available Examples"]').should('be.visible');
  });
});
